 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each solid 3x3 square emits horizontal and vertical rays from its center.
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color for rr in range(r, r + 3) for cc in range(c, c + 3)):
                centers.append((r + 1, c + 1, color))
    axes = {}
    for r, c, color in centers:
        axes.setdefault(color, []).append((r, c))
    for r, c, color in centers:
        for x in range(w):
            out[r][x] = color
        for y in range(h):
            out[y][c] = color
    # Crossing rays of different colors are cut to background.
    for r, c, color in centers:
        for other_r, other_c, other_color in centers:
            if color != other_color:
                if r == other_r:
                    out[r][other_c] = 0
                if c == other_c:
                    out[other_r][c] = 0
    return out
